      "tipo": "GPU",
      "causa_raiz": "O tempo de renderização da GPU atingiu 32.76 ms (2095 violações do orçamento de 16.7 ms para 60 FPS), caracterizando um gargalo massivo de GPU. A causa provável em hardwares como a GTX 1650 envolve excesso de sobreposição de renderização (overdraw), shaders de fragmento excessivamente complexos, alta densidade de luzes dinâmicas com projeção de sombras em tempo real e pós-processamento pesado (como SSAO, Bloom com muitas passagens e sombras de alta resolução).",
      "codigo_refatorado": "using UnityEngine;
using UnityEngine.Rendering;

public class AdaptiveGpuScaler : MonoBehaviour
{
    [Header("Resolution Settings")]
    [SerializeField] private float minResolutionScale = 0.65f;
    [SerializeField] private float maxResolutionScale = 1.0f;
    [SerializeField] private float targetFrameTimeMs = 16.0f;
    [SerializeField] private float scaleStep = 0.05f;
    [SerializeField] private float evaluationInterval = 0.5f;

    [Header("Shadows & Lighting")]
    [SerializeField] private Light mainDirectionalLight;
    [SerializeField] private float normalShadowDistance = 50f;
    [SerializeField] private float reducedShadowDistance = 25f;

    private float currentScale = 1.0f;
    private float timer = 0f;
    private FrameTiming[] frameTimings = new FrameTiming[1];

    private void Awake()
    {
        QualitySettings.vSyncCount = 0;
        Application.targetFrameRate = 60;
        currentScale = maxResolutionScale;
    }

    private void Update()
    {
        timer += Time.unscaledDeltaTime;
        if (timer < evaluationInterval) return;
        timer = 0f;

        FrameTimingManager.CaptureFrameTimings();
        uint captured = FrameTimingManager.GetLatestTimings(1, frameTimings);

        float gpuDuration = captured > 0 ? (float)frameTimings[0].gpuFrameTime : (Time.unscaledDeltaTime * 1000f);

        if (gpuDuration > targetFrameTimeMs)
        {
            currentScale = Mathf.Max(minResolutionScale, currentScale - scaleStep);
            QualitySettings.shadowDistance = reducedShadowDistance;
            if (mainDirectionalLight != null)
            {
                mainDirectionalLight.shadowResolution = LightShadowResolution.Low;
            }
        }
        else if (gpuDuration < (targetFrameTimeMs - 3.0f))
        {
            currentScale = Mathf.Min(maxResolutionScale, currentScale + scaleStep);
            QualitySettings.shadowDistance = normalShadowDistance;
            if (mainDirectionalLight != null)
            {
                mainDirectionalLight.shadowResolution = LightShadowResolution.Medium;
            }
        }

        ScalableBufferManager.ResizeBuffers(currentScale, currentScale);
    }
}",
      "explicacao_didatica": "A GPU (placa de vídeo) está demorando quase o dobro do tempo permitido para pintar cada quadro na tela (32.76 ms em vez dos 16.7 ms necessários para manter 60 FPS). O script refatorado monitora o tempo de resposta da GPU sem criar lixo na memória (evitando travamentos do coletor de lixo - GC) e reduz dinamicamente a resolução interna do jogo e a distância das sombras quando o jogo detecta lentidão, permitindo que a GTX 1650 desenhe as imagens com muito mais agilidade sem comprometer a estabilidade do jogo."
    },
    {
      "tipo": "GC",
      "causa_raiz": "Ocorrência de alocação de memória transiente (36.8 KB no frame amostrado e até 98.9 KB de pico), provocando pausas de coleta de lixo (GC Collect) de 5.58 ms. Em taxas de 60 FPS, uma pausa de 5.58 ms consome um terço de todo o tempo disponível no frame, gerando micro-engasgos (stutters).",
      "codigo_refatorado": "using UnityEngine;

public class OptimizedMeshVisibilityManager : MonoBehaviour
{
    [SerializeField] private Renderer[] managedRenderers;
    private Plane[] cameraFrustumPlanes = new Plane[6];
    private Camera targetCamera;

    private void Awake()
    {
        targetCamera = Camera.main;
        if (managedRenderers == null || managedRenderers.Length == 0)
        {
            managedRenderers = FindObjectsByType<Renderer>(FindObjectsSortMode.None);
        }
    }

    private void Update()
    {
        if (targetCamera == null) return;

        GeometryUtility.CalculateFrustumPlanes(targetCamera, cameraFrustumPlanes);

        for (int i = 0; i < managedRenderers.Length; i++)
        {
            Renderer rend = managedRenderers[i];
            if (rend != null)
            {
                bool isVisible = GeometryUtility.TestPlanesAABB(cameraFrustumPlanes, rend.bounds);
                if (rend.enabled != isVisible)
                {
                    rend.enabled = isVisible;
                }
            }
        }
    }
}",
      "explicacao_didatica": "Toda vez que alocamos memória no C# que dura pouco tempo (como listas temporárias ou busca de objetos a cada frame), o Garbage Collector precisa parar a execução para limpar essa sujeira, criando 'travadinhas'. O código foi ajustado para reutilizar os mesmos espaços de memória (arrays de tamanho fixo calculados na inicialização), garantindo zero alocações por frame."
    }
  ],
  "dicas_level_design": "Os Draw Calls atingiram o pico de 2797, violando o orçamento de 2579: 1) Ative e bakeie 'Occlusion Culling' em toda a geometria estática para evitar que paredes e cenários escondidos sejam enviados para a GPU. 2) Crie e aplique LODs (Levels of Detail) para meshes complexos, reduzindo a complexidade de vértices e submateriais à distância. 3) Configure Texture Atlasing e consolidação de materiais usando shaders unificados (Standard/Lit) para maximizar o 'Static Batching' e 'GPU Instancing'. 4) Elimine luzes dinâmicas adicionais com projeção de sombra; utilize Lightmaps assados (Baked Global Illumination) com Light Probes para objetos dinâmicos. 5) Reduza o overdraw limitando sistemas de partículas com materiais transparentes/aditivos empilhados em close-up na câmera."
}

